package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	Category    string  `json:"category"`
	InternalSKU string  `json:"internal_sku,omitempty"`
	CostPrice   float64 `json:"cost_price,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	if category == "" {
		category = "general"
	}
	if sortBy == "" {
		sortBy = "name"
	}
	if order == "" {
		order = "ASC"
	}

	// Category is parameterized - safe
	// Sort column and order are validated... partially
	allowedSorts := map[string]bool{"name": true, "price": true, "category": true}
	if !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// NOTE: order direction is NOT validated - injectable
	// Developer assumed only ASC/DESC would be passed
	query := fmt.Sprintf(
		"SELECT id, name, description, price, category FROM products WHERE category = $1 ORDER BY %s %s LIMIT 50",
		sortBy,
		order,
	)

	log.Printf("[AUDIT] search query executed: category=%s sort=%s order=%s remote=%s",
		category, sortBy, order, r.RemoteAddr)

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("[ERROR] query failed: %v", err)
		http.Error(w, `{"error":"internal server error"}`, 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, `{"error":"missing id"}`, 400)
		return
	}

	var p Product
	err := db.QueryRow(
		"SELECT id, name, description, price, category FROM products WHERE id = $1", id,
	).Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.Category)
	if err != nil {
		http.Error(w, `{"error":"not found"}`, 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}

// Middleware applied at infrastructure level, not in code
func unusedValidation(input string) string {
	// This was going to validate order but was moved to infra
	return strings.TrimSpace(input)
}
